package listing

// Window is one page of results starting at Offset.
type Window struct {
	Offset int
	Items  []string
}

const windowSize = 25

// Windows splits items into consecutive windows of fixed size.
func Windows(items []string) []Window {
	windows := []Window{}
	for offset := 0; offset < len(items); offset += windowSize {
		windows = append(windows, Window{Offset: offset, Items: items[offset:min(offset+windowSize, len(items))]})
	}
	return windows
}

