package listing

import "testing"

func TestWindowsSplitsIntoTwentyFives(t *testing.T) {
	items := make([]string, 60)
	windows := Windows(items)
	if len(windows) != 3 || windows[2].Offset != 50 || len(windows[2].Items) != 10 {
		t.Fatalf("windows = %+v", windows)
	}
}
